const input = $input.first().json || {};
const source = input.body || input;

const includeYoutube =
  source.include_youtube === true ||
  source.include_youtube === 'true';

return [{
  json: {
    body: {
      country: source.country || 'US',
      keyword: source.keyword || '',
      include_youtube: includeYoutube
    }
  }
}];

// 입력값 통합 노드에서 국가, 키워드, YouTube 포함 여부를 가져옵니다.
const triggerBody = $('입력값 통합1').first().json.body || {};

const country = triggerBody.country || 'PL';
const originalKeyword = triggerBody.keyword || '세탁건조기';

const includeYoutube =
  triggerBody.include_youtube === true ||
  triggerBody.include_youtube === 'true';

// 앞의 AI 노드가 만든 사이트 목록을 읽습니다.
const firstItem = $input.first().json || {};

const rawText =
  firstItem.text ||
  firstItem.output ||
  firstItem.response ||
  firstItem.message?.content ||
  '[]';

let parsedList = [];

try {
  // AI 응답에 ```json 코드 블록이 있으면 제거합니다.
  const cleanedText = String(rawText)
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  // 응답에서 JSON 배열 부분을 찾습니다.
  const arrayMatch = cleanedText.match(/\[[\s\S]*\]/);
  const jsonText = arrayMatch ? arrayMatch[0] : cleanedText;

  const parsed = JSON.parse(jsonText);

  if (Array.isArray(parsed)) {
    parsedList = parsed;
  } else if (Array.isArray(parsed.links)) {
    parsedList = parsed.links;
  } else if (Array.isArray(parsed.items)) {
    parsedList = parsed.items;
  } else if (parsed && typeof parsed === 'object') {
    parsedList = [parsed];
  }
} catch (error) {
  throw new Error(
    `사이트 목록 JSON 파싱 실패: ${error.message}\n\n원본 응답:\n${rawText}`
  );
}

// URL에서 도메인을 추출합니다.
function getHost(url) {
  try {
    return new URL(url).hostname.replace(/^www\./, '').toLowerCase();
  } catch {
    return '';
  }
}

// 일반 쇼핑몰, 리뷰 사이트, Reddit 목록을 만듭니다.
const resultItems = parsedList
  .map(item => {
    let rawUrl = String(
      item.url ||
      item.URL ||
      item.domain ||
      ''
    ).trim();

    // AI가 [사이트](https://주소) 형식으로 반환한 경우 URL만 추출합니다.
    const markdownLink = rawUrl.match(
      /\]\((https?:\/\/[^)\s]+)\)/
    );

    if (markdownLink) {
      rawUrl = markdownLink[1];
    }

    // https://가 없는 도메인을 보정합니다.
    if (
      rawUrl &&
      !/^https?:\/\//i.test(rawUrl)
    ) {
      rawUrl = `https://${rawUrl.replace(/^\/+/, '')}`;
    }

    if (!rawUrl) {
      return null;
    }

    const localKeyword =
      item.local_keyword ||
      item.keyword ||
      originalKeyword;

    const host = getHost(rawUrl);
    const isReddit = host.includes('reddit.com');

    return {
      json: {
        url: rawUrl,
        fallback_urls: [],
        category:
          item.category ||
          (isReddit ? 'Community/Forum' : 'E-commerce'),
        site_name:
          item.site_name ||
          item.name ||
          (isReddit ? 'Reddit' : host || 'Unknown'),
        country: String(
          item.country_code ||
          item.country ||
          country
        ).toUpperCase(),
        keyword: localKeyword,
        original_keyword: originalKeyword
      }
    };
  })
  .filter(Boolean);

// 대시보드에서 YouTube 포함을 체크한 경우에만 추가합니다.
if (includeYoutube) {
  const localKeyword =
    resultItems[0]?.json?.keyword ||
    originalKeyword;

  resultItems.push({
    json: {
      url:
        `https://www.youtube.com/results?search_query=` +
        encodeURIComponent(localKeyword),
      fallback_urls: [],
      category: 'Video/YouTube',
      site_name: 'YouTube',
      country: String(country).toUpperCase(),
      keyword: localKeyword,
      original_keyword: originalKeyword
    }
  });
}

return resultItems;

// 시트 2(Reddit)와 시트 3(일반사이트)이 루프를 돌며 뱉어낸 모든 실행 결과를 빠짐없이 긁어모읍니다.
let allVocItems = [];

// 1) 시트 2(Reddit)의 모든 루프 결과 수집
try {
  const sheet2Items = $items("Call [시트 2: Reddit 수집기]2");
  allVocItems.push(...sheet2Items.map(i => i.json));
} catch (e) {}

// 3) 시트 4(YouTube) 결과 수집 추가
try {
  const sheet4Items = $items("Call [시트 4: YouTube 수집기]");
  allVocItems.push(...sheet4Items.map(i => i.json));
} catch (e) {}

// 2) 시트 3(ScrapingAnt)의 모든 루프 결과 수집
try {
  const sheet3Items = $items("Call [시트 3: ScrapingAnt 수집기]2");
  allVocItems.push(...sheet3Items.map(i => i.json));
} catch (e) {}

// 혹시 기본 input으로 들어온 값도 있다면 합치고 voc_id 기준으로 중복 제거
const directInputs = $input.all().map(i => i.json);
allVocItems.push(...directInputs);

const uniqueMap = new Map();
for (const item of allVocItems) {
  if (item && item.voc_id && item.content) {
    uniqueMap.set(item.voc_id, item);
  }
}
const validVocList = Array.from(uniqueMap.values());

const BATCH_SIZE = 15;
const batches = [];

for (let i = 0; i < validVocList.length; i += BATCH_SIZE) {
  const chunk = validVocList.slice(i, i + BATCH_SIZE);
  batches.push({
    json: {
      original_items: chunk,
      llm_payload: JSON.stringify(chunk.map(v => ({
        voc_id: v.voc_id,
        content: String(v.content).substring(0, 800)
      })))
    }
  });
}

return batches;

const batchNode = $('Loop Over VOC Batches1').first().json;
const originals = batchNode.original_items || [];

const firstItem = $input.first().json;
const rawText = firstItem.text || firstItem.output || firstItem.response || '[]';

let aiResults = [];
try {
  const match = String(rawText).match(/\[[\s\S]*\]/);
  const jsonStr = match ? match[0] : String(rawText).replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(jsonStr);
  aiResults = Array.isArray(parsed) ? parsed : (parsed.items || parsed.results || [parsed]);
} catch (e) {
  aiResults = [];
}

const aiMap = new Map();
for (const item of aiResults) {
  if (item && item.voc_id) {
    aiMap.set(String(item.voc_id), item);
  }
}

const country =$('입력값 통합1').first().json.body?.country || 'US';
const keyword = $('입력값 통합1').first().json.body?.keyword || 'Unknown';

// 브랜드 표기 통일: "SAMSUNG"/"samsung" → "Samsung", LG/GE/AEG 같은 3글자 이하는 대문자
// "General"/"Comparison"/"Unknown" 같은 값은 브랜드가 아니므로 빈 값으로 취급
function normBrand(b) {
  const s = String(b || '').trim();
  if (!s || /^(general|comparison|unknown|n\/a|none|brak)$/i.test(s)) return '';
  const canonical = {
    lg: 'LG', samsung: 'Samsung', bosch: 'Bosch', whirlpool: 'Whirlpool',
    miele: 'Miele', electrolux: 'Electrolux', ge: 'GE', aeg: 'AEG',
    amana: 'Amana', beko: 'Beko', haier: 'Haier', siemens: 'Siemens',
    'speed queen': 'Speed Queen', maytag: 'Maytag', kenmore: 'Kenmore',
    panasonic: 'Panasonic', philips: 'Philips', dyson: 'Dyson'
  };
  return canonical[s.toLowerCase()] || (s.length <= 3 ? s.toUpperCase() : s.charAt(0).toUpperCase() + s.slice(1).toLowerCase());
}

// AI가 General을 반환했을 때 원문에 명시된 브랜드가 정확히 하나면 안전하게 보정합니다.
// 여러 브랜드가 있으면 주 평가 대상을 임의로 고르지 않고 AI 결과를 유지합니다.
function brandsInContent(content) {
  const text = String(content || '');
  const patterns = [
    ['LG', /(?<![A-Za-z0-9])(?:LG|엘지)(?![A-Za-z0-9])/i],
    ['Samsung', /(?<![A-Za-z0-9])(?:Samsung|삼성)(?![A-Za-z0-9])/i],
    ['Bosch', /(?<![A-Za-z0-9])Bosch(?![A-Za-z0-9])/i],
    ['Whirlpool', /(?<![A-Za-z0-9])Whirlpool(?![A-Za-z0-9])/i],
    ['Miele', /(?<![A-Za-z0-9])Miele(?![A-Za-z0-9])/i],
    ['Electrolux', /(?<![A-Za-z0-9])Electrolux(?![A-Za-z0-9])/i],
    ['GE', /(?<![A-Za-z0-9])GE(?![A-Za-z0-9])/i],
    ['AEG', /(?<![A-Za-z0-9])AEG(?![A-Za-z0-9])/i],
    ['Amana', /(?<![A-Za-z0-9])Amana(?![A-Za-z0-9])/i],
    ['Beko', /(?<![A-Za-z0-9])Beko(?![A-Za-z0-9])/i],
    ['Haier', /(?<![A-Za-z0-9])Haier(?![A-Za-z0-9])/i],
    ['Siemens', /(?<![A-Za-z0-9])Siemens(?![A-Za-z0-9])/i],
    ['Speed Queen', /(?<![A-Za-z0-9])Speed\s+Queen(?![A-Za-z0-9])/i],
    ['Maytag', /(?<![A-Za-z0-9])Maytag(?![A-Za-z0-9])/i],
    ['Kenmore', /(?<![A-Za-z0-9])Kenmore(?![A-Za-z0-9])/i]
  ];
  return patterns.filter(([, re]) => re.test(text)).map(([brand]) => brand);
}

function toBrandArray(value) {
  if (Array.isArray(value)) return value;
  if (typeof value !== 'string' || !value.trim()) return [];
  try { const parsed = JSON.parse(value); return Array.isArray(parsed) ? parsed : [parsed]; }
  catch (e) { return value.split(/[;,|]/); }
}
// 시트 3이 상품 페이지에서 붙인 말머리: [Brand: X | Product: Y | Model: Z | Rating: …]
function parsePrefix(content) {
  const m = String(content || '').match(/^\s*\[Brand:\s*([^|\]]*)\|\s*Product:\s*([^|\]]*)\|\s*Model:\s*([^|\]]*)/i);
  if (!m) return {};
  const clean = v => { const t = v.trim(); return /^(general|unknown|n\/a|none)?$/i.test(t) ? '' : t; };
  return { brand: normBrand(m[1]), product: clean(m[2]), model: clean(m[3]) };
}

return originals.map(orig => {
  const ai = aiMap.get(String(orig.voc_id)) || {};
  // 브랜드/제품/모델은 상품 페이지 말머리 > AI 추출 순으로 사용
  const pre = parsePrefix(orig.content);
  const detectedBrands = brandsInContent(orig.content);
  const targetBrand = pre.brand || normBrand(ai.target_brand) || (detectedBrands.length === 1 ? detectedBrands[0] : '') || 'General';
  const mentioned = [...new Map([...toBrandArray(ai.competitors), ...detectedBrands]
    .map(normBrand).filter(Boolean).map(b => [b.toLowerCase(), b])).values()]
    .filter(b => b.toLowerCase() !== targetBrand.toLowerCase());
  return {
    json: {
      voc_id: orig.voc_id,
      country: country,
      keyword: keyword,
      source_site: orig.source_site || 'Unknown',         // 개별 사이트명 (Reddit, Amazon, MediaExpert 등)
      category: orig.category || 'Community/Forum',       // 채널 구분 (E-commerce vs Community/Forum)
      content_type: orig.content_type || 'POST',          // 글 유형 (REVIEW, POST, COMMENT)
      content: orig.content || '',
      parent_id: orig.parent_id || null,
      published_at: orig.published_at || null,
      product_category: ai.product_category || keyword,   // 1단계: 제품군
      target_brand: targetBrand,                          // 2단계: 브랜드 (리뷰가 평가하는 브랜드 1개, Comparison 없음)
      product_line: pre.product || ai.product_line || 'General',  // 3단계: 제품명
      model_code: pre.model || ai.model_code || 'Unknown',        // 4단계: 모델명
      positive_keywords: Array.isArray(ai.positive_keywords) ? ai.positive_keywords : [], // ★ 긍정 키워드
      negative_keywords: Array.isArray(ai.negative_keywords) ? ai.negative_keywords : [], // ★ 부정 키워드
      topic_tags: Array.isArray(ai.topic_tags) ? ai.topic_tags : [],                      // ★ 전체 언급 키워드
      kr_summary: ai.kr_summary || '(AI 요약 실패 또는 내용 없음)',
      ai_sentiment: ai.ai_sentiment || 'NEUTRAL',
      user_intent: ai.user_intent || 'EXPERIENCE',        // ★ 채널별 반응 성향 (후기/질문/불만/비교)
      competitors: mentioned,                             // target_brand 외에 함께 언급된 브랜드
      ai_metadata: {
        lg_mentioned: Boolean(ai.lg_mentioned),
        // ★ 대시보드 분리 기준: 브랜드가 명확하고 긍/부정 키워드가 있으면 PRODUCT_REVIEW(탭1), 일상 고충이면 LIFE_PAINPOINT(탭2), 나머지는 MARKET_TREND(탭2)
        dashboard_type: (targetBrand !== 'General' && ((Array.isArray(ai.positive_keywords) && ai.positive_keywords.length > 0) || (Array.isArray(ai.negative_keywords) && ai.negative_keywords.length > 0)))
          ? 'PRODUCT_REVIEW'
          : ((ai.user_intent === 'PAINPOINT' || (targetBrand === 'General' && Array.isArray(ai.negative_keywords) && ai.negative_keywords.length > 0))
            ? 'LIFE_PAINPOINT'
            : 'MARKET_TREND'),
        analyzed_at: new Date().toISOString()
      }
    }
  };
});

